13	// PackageDelivery 是指定接收方取包时得到的视图：交换标识、当前状态、
14	// 创建时间、包内容与摘要，不含内部使用者标识等包外信息。
15	type PackageDelivery struct {
16		ExchangeID ID
17		Status     string
18		Digest     string
19		CreatedAt  time.Time
20		Package    Package
21	}
22	
23	// ReceiptConfirmation 是接收方登记回执后得到的确认。
24	// 只含交换标识、当前状态、回执结果与登记时间，不含任何受保护内容；
25	// 授权失效或患者停用后登记回执也只返回该确认。
26	type ReceiptConfirmation struct {
27		ExchangeID   ID
28		Status       string
29		Outcome      string
30		RegisteredAt time.Time
31	}
32	
33	// CreateExchange 由内部使用者把一条当前有效授权覆盖的已生效记录集合打包给
34	// 指定接收方。
35	//
36	// 参数：患者、接收方、绑定授权、记录标识集合与非空请求号。记录必须属于该
37	// 患者且已经生效；每条记录都必须被绑定的那一条授权覆盖——整类范围按记录的
38	// 就诊+类别覆盖，限定范围只覆盖明确选中的记录，不能借用同一接收方的其他
39	// 授权补足。授权必须属于该患者与接收方且在当前时间有效。空集合、空白请求号、
40	// 不存在或跨患者的引用、夹带草稿、记录不被绑定授权覆盖、授权不符一律拒绝，
41	// 不留下交换或审计，也不占用请求号。患者停用后不能新建交换。
42	//
43	// 成功后包内容固化为创建时各记录的当前生效版本（重复记录标识合并），并计算
44	// 稳定摘要，状态为待回执；交换与审计事件在同一次原子落盘中保留。此后记录被
45	// 更正或有新版本、新增记录都不会改写已创建的包。
46	//
47	// 请求号按发起的内部使用者区分：同一使用者以相同请求号携带相同患者、接收方、
48	// 授权与记录集合（顺序不限）重试时，返回原交换及其现有状态，不重新取内容、
49	// 不新增审计；其他参数变化返回 ErrConflict。首次失败不占用请求号。
50	func (s *Store) CreateExchange(actor Actor, patientID ID, receiverID, authorizationID ID, recordIDs []ID, requestID string) (Exchange, error) {
51		if !actor.valid() || !actor.IsInternal() {
52			return Exchange{}, ErrAccessDenied
53		}
54		if patientID == "" {
55			return Exchange{}, fmt.Errorf("%w: patient id is required", ErrInvalidArgument)
56		}
57		if strings.TrimSpace(receiverID) == "" {
58			return Exchange{}, fmt.Errorf("%w: receiver id is required", ErrInvalidArgument)
59		}
60		if strings.TrimSpace(authorizationID) == "" {
61			return Exchange{}, fmt.Errorf("%w: authorization id is required", ErrInvalidArgument)
62		}
63		if strings.TrimSpace(requestID) == "" {
64			return Exchange{}, fmt.Errorf("%w: request id is required", ErrInvalidArgument)
65		}
66		if len(recordIDs) == 0 {
67			return Exchange{}, fmt.Errorf("%w: record id set must not be empty", ErrInvalidArgument)
68		}
69		for _, rid := range recordIDs {
70			if strings.TrimSpace(rid) == "" {
71				return Exchange{}, fmt.Errorf("%w: record id must not be blank", ErrInvalidArgument)
72			}
73		}
74		wanted := uniqueSortedIDs(recordIDs)
75	
76		var result Exchange
77		err := s.mutate(func(snap *snapshot) error {
78			// 幂等检索优先：同一使用者的同一请求号无论当前患者/授权状态如何，
79			// 都只返回原结果（重试不是新建）。
80			if existing := findExchangeByRequest(snap, actor.ID, requestID); existing != nil {
81				if !sameExchangeRequest(existing, patientID, receiverID, authorizationID, wanted) {
82					return fmt.Errorf("%w: request id %q already used with different parameters", ErrConflict, requestID)
83				}
84				result = *existing
85				if existing.Receipt != nil {
86					r := *existing.Receipt
87					result.Receipt = &r
88				}
89				result.Package.Records = append([]PackagedRecord(nil), existing.Package.Records...)
90				return nil
91			}
92	
93			// 首次创建：患者必须存在且未停用。
94			if _, err := requireActivePatient(snap, patientID); err != nil {
95				return err
96			}
97	
98			// 绑定授权必须存在、属于该患者与接收方、当前有效。
99			a := snap.Authorizations[authorizationID]
100			if a == nil {
101				return fmt.Errorf("%w: authorization %q", ErrNotFound, authorizationID)
102			}
103			if a.PatientID != patientID {
104				return fmt.Errorf("%w: authorization %q belongs to patient %q, not %q",
105					ErrMismatchedPatient, authorizationID, a.PatientID, patientID)
106			}
107			if a.ReceiverID != receiverID {
108				return fmt.Errorf("%w: authorization %q is bound to receiver %q, not %q",
109					ErrInvalidArgument, authorizationID, a.ReceiverID, receiverID)
110			}
111			now := s.now()
112			if !a.ActiveAt(now) {
113				// 未开始、已到期或已撤回：没有覆盖此次打包的有效授权。
114				return fmt.Errorf("%w: authorization %q is not active", ErrAccessDenied, authorizationID)
115			}
116	
117			// 逐记录固化当前生效版本；重复标识已合并，按记录标识排序保证确定性。
118			pkg := Package{PatientID: patientID, ReceiverID: receiverID}
119			for _, rid := range wanted {
120				r := snap.Records[rid]
121				if r == nil {
122					return fmt.Errorf("%w: record %q", ErrNotFound, rid)
123				}
124				if r.PatientID != patientID {
125					return fmt.Errorf("%w: record %q belongs to patient %q, not %q",
126						ErrMismatchedPatient, rid, r.PatientID, patientID)
127				}
128				if r.CurrentVersionID == "" {
129					return fmt.Errorf("%w: record %q has no effective version; activate its draft first",
130						ErrInvalidArgument, rid)
131				}
132				v := snap.Versions[r.CurrentVersionID]
133				if v == nil {
134					return fmt.Errorf("%w: current version %q of record %q", ErrNotFound, r.CurrentVersionID, rid)
135				}
136				// 每条记录都必须被绑定授权自身覆盖：整类范围或限定范围。
137				// 同一接收方的其他授权不能补足；夹带一条未覆盖记录即整包拒绝。
138				if !authorizationCoversRecord(a, r) {
139					return fmt.Errorf("%w: record %q (encounter %q, category %q) is not covered by authorization %q",
140						ErrAccessDenied, rid, r.EncounterID, r.Category, authorizationID)
141				}
142				pkg.Records = append(pkg.Records, PackagedRecord{
143					EncounterID: r.EncounterID,
144					Category:    r.Category,
145					RecordID:    r.ID,
146					VersionID:   v.ID,
147					Version:     v.Number,
148					EffectiveAt: v.CreatedAt,
149					Content:     v.Content,
150				})
151			}
152	
153			x := &Exchange{
154				ID:              newID("exch"),
155				PatientID:       patientID,
156				ReceiverID:      receiverID,
157				AuthorizationID: authorizationID,
158				RequestID:       requestID,
159				CreatorID:       actor.ID,
160				Status:          ExchangePending,
161				Digest:          packageDigest(pkg),
162				Package:         pkg,
163				CreatedAt:       now,
164			}
165			snap.Exchanges[x.ID] = x
166			s.addAudit(snap, patientID, actor, ActionExchanged, "exchange", x.ID, now)
167			result = *x
168			result.Package.Records = append([]PackagedRecord(nil), x.Package.Records...)
169			return nil
170		})
171		return result, err
172	}
173	
174	// FetchPackage 供指定接收方凭交换标识取包。
175	//
176	// 每次取包都重新检查绑定授权与患者状态：授权必须仍是创建时绑定的那一条且
177	// 已开始、未到期、未撤回，患者档案必须未停用；其他有效授权不能替代绑定授权。
178	// 授权未开始、到期、撤回或患者停用后返回 ErrAccessDenied，不返回包内容或摘要。
179	// 其他接收方、内部使用者以及不存在的交换统一拒绝，不泄露交换是否存在。
180	func (s *Store) FetchPackage(actor Actor, exchangeID ID) (PackageDelivery, error) {
181		if !actor.valid() || actor.Kind != "receiver" {
182			return PackageDelivery{}, ErrAccessDenied
183		}
184		if strings.TrimSpace(exchangeID) == "" {
185			return PackageDelivery{}, fmt.Errorf("%w: exchange id is required", ErrInvalidArgument)
186		}
187	
188		now := s.now()
189		var out PackageDelivery
190		err := s.view(func(snap *snapshot) error {
191			x := snap.Exchanges[exchangeID]
192			if x == nil || x.ReceiverID != actor.ID {
193				// 不存在或属于其他接收方：统一拒绝，不泄露存在性。
194				return ErrAccessDenied
195			}
196			p := snap.Patients[x.PatientID]
197			if p == nil || p.Deactivated {
198				return ErrAccessDenied
199			}
200			// 必须仍是绑定的那条授权（同一患者与接收方）；其他有效授权不能替代。
201			a := snap.Authorizations[x.AuthorizationID]
202			if a == nil || a.PatientID != x.PatientID || a.ReceiverID != actor.ID || !a.ActiveAt(now) {
203				return ErrAccessDenied
204			}
205			out = PackageDelivery{
206				ExchangeID: x.ID,
207				Status:     x.Status,
208				Digest:     x.Digest,
209				CreatedAt:  x.CreatedAt,
210				Package:    clonePackage(x.Package),
211			}
212			return nil
213		})
214		return out, err
215	}
216	
217	// SubmitReceipt 供指定接收方对一份包登记回执：提供交换标识、取包时得到的
218	// 包摘要、接受或拒绝的结果及原因。
219	//
220	// 非法结果、拒绝时原因为空白返回 ErrInvalidArgument。只有指定接收方且摘要
221	// 吻合，才能把交换从待回执变为已接受或已拒绝；摘要不符返回 ErrConflict，
222	// 状态不变。相同回执（结果与原因均相同）重交返回原确认，不新增审计；结果
223	// 或原因改变返回 ErrConflict。其他身份不能代交，不存在的交换统一拒绝。
224	//
225	// 授权失效或患者停用后仍允许登记此前包的回执，但响应只返回确认状态，
226	// 不提供任何受保护内容。
227	func (s *Store) SubmitReceipt(actor Actor, exchangeID ID, digest, outcome, reason string) (ReceiptConfirmation, error) {
228		if !actor.valid() || actor.Kind != "receiver" {
229			return ReceiptConfirmation{}, ErrAccessDenied
230		}
231		if strings.TrimSpace(exchangeID) == "" {
232			return ReceiptConfirmation{}, fmt.Errorf("%w: exchange id is required", ErrInvalidArgument)
233		}
234		if outcome != ReceiptAccepted && outcome != ReceiptRejected {
235			return ReceiptConfirmation{}, fmt.Errorf("%w: outcome must be %q or %q", ErrInvalidArgument, ReceiptAccepted, ReceiptRejected)
236		}
237		if outcome == ReceiptRejected && strings.TrimSpace(reason) == "" {
238			return ReceiptConfirmation{}, fmt.Errorf("%w: rejection reason is required", ErrInvalidArgument)
239		}
240		if outcome == ReceiptAccepted {
241			// 接受不携带原因；统一归一化，保证重复提交判定稳定。
242			reason = ""
243		}
244	
245		var conf ReceiptConfirmation
246		err := s.mutate(func(snap *snapshot) error {
247			x := snap.Exchanges[exchangeID]
248			if x == nil || x.ReceiverID != actor.ID {
249				// 不存在或属于其他接收方/其他身份：统一拒绝。
250				return ErrAccessDenied
251			}
252			if digest != x.Digest {
253				return fmt.Errorf("%w: package digest does not match exchange %q", ErrConflict, exchangeID)
254			}
255			if x.Receipt != nil {
256				if x.Receipt.Outcome != outcome || x.Receipt.Reason != reason {
257					return fmt.Errorf("%w: exchange %q already has a different receipt", ErrConflict, exchangeID)
258				}
259				// 相同回执重交：返回原确认，不新增审计、不改状态。
260				conf = ReceiptConfirmation{
261					ExchangeID:   x.ID,
262					Status:       x.Status,
263					Outcome:      x.Receipt.Outcome,
264					RegisteredAt: x.Receipt.RegisteredAt,
265				}
266				return nil
267			}
268	
269			now := s.now()
270			x.Receipt = &Receipt{Outcome: outcome, Reason: reason, RegisteredAt: now}
271			if outcome == ReceiptAccepted {
272				x.Status = ExchangeAccepted
273			} else {
274				x.Status = ExchangeRejected
275			}
276			s.addAudit(snap, x.PatientID, actor, ActionReceipted, "exchange", x.ID, now)
277			conf = ReceiptConfirmation{
278				ExchangeID:   x.ID,
279				Status:       x.Status,
280				Outcome:      outcome,
281				RegisteredAt: now,
282			}
283			return nil
284		})
285		return conf, err
286	}
287	
288	// GetExchange 供内部使用者按患者查看原包（含固化内容与摘要）及回执。
289	// 患者停用后仍可查看。交换不存在返回 ErrNotFound，属于其他患者返回
290	// ErrMismatchedPatient。
291	func (s *Store) GetExchange(actor Actor, patientID, exchangeID ID) (Exchange, error) {
292		if !actor.valid() || !actor.IsInternal() {
293			return Exchange{}, ErrAccessDenied
294		}
295		var result Exchange
296		err := s.view(func(snap *snapshot) error {
297			x, err := requireExchange(snap, patientID, exchangeID)
298			if err != nil {
299				return err
300			}
301			result = cloneExchangeValue(x)
302			return nil
303		})
304		return result, err
305	}
306	
307	// ListExchanges 供内部使用者按患者查看其全部交换（原包与回执），
308	// 按创建时间旧到新排序；时间戳相同时按交换标识排序。患者停用后仍可查看。
309	func (s *Store) ListExchanges(actor Actor, patientID ID) ([]Exchange, error) {
310		if !actor.valid() || !actor.IsInternal() {
311			return nil, ErrAccessDenied
312		}
313		var result []Exchange
314		err := s.view(func(snap *snapshot) error {
315			if _, err := requirePatient(snap, patientID); err != nil {
316				return err
317			}
318			for _, x := range snap.Exchanges {
319				if x.PatientID == patientID {
320					result = append(result, cloneExchangeValue(x))
321				}
322			}
323			sort.Slice(result, func(i, j int) bool {
324				if !result[i].CreatedAt.Equal(result[j].CreatedAt) {
325					return result[i].CreatedAt.Before(result[j].CreatedAt)
326				}
327				return result[i].ID < result[j].ID
328			})
329			return nil
330		})
331		return result, err
332	}
333	
334	func requireExchange(snap *snapshot, patientID, exchangeID ID) (*Exchange, error) {
335		x := snap.Exchanges[exchangeID]
336		if x == nil {
337			return nil, fmt.Errorf("%w: exchange %q", ErrNotFound, exchangeID)
338		}
339		if x.PatientID != patientID {
340			return nil, fmt.Errorf("%w: exchange %q belongs to patient %q, not %q",
341				ErrMismatchedPatient, exchangeID, x.PatientID, patientID)
342		}
343		return x, nil
344	}
345	
346	func findExchangeByRequest(snap *snapshot, creatorID, requestID string) *Exchange {
347		for _, x := range snap.Exchanges {
348			if x.CreatorID == creatorID && x.RequestID == requestID {
349				return x
350			}
351		}
352		return nil
353	}
354	
355	// sameExchangeRequest 判断重试参数是否与既有交换完全一致（记录集合顺序无关）。
356	func sameExchangeRequest(x *Exchange, patientID ID, receiverID, authorizationID ID, wantedRecordIDs []ID) bool {
357		if x.PatientID != patientID || x.ReceiverID != receiverID || x.AuthorizationID != authorizationID {
358			return false
359		}
360		if len(x.Package.Records) != len(wantedRecordIDs) {
361			return false
362		}
363		// 包内记录按记录标识排序保存，wantedRecordIDs 同样已去重排序。
364		for i, pr := range x.Package.Records {
365			if pr.RecordID != wantedRecordIDs[i] {
366				return false
367			}
368		}
369		return true
370	}
371	
372	func uniqueSortedIDs(ids []ID) []ID {
373		seen := make(map[ID]struct{}, len(ids))
374		out := make([]ID, 0, len(ids))
375		for _, id := range ids {
376			if _, ok := seen[id]; ok {
377				continue
378			}
379			seen[id] = struct{}{}
380			out = append(out, id)
381		}
382		sort.Strings(out)
383		return out
384	}
385	
386	func clonePackage(p Package) Package {
387		p.Records = append([]PackagedRecord(nil), p.Records...)
388		return p
389	}
390	
391	func cloneExchangeValue(x *Exchange) Exchange {
392		y := *x
393		y.Package = clonePackage(x.Package)
394		if x.Receipt != nil {
395			r := *x.Receipt
396			y.Receipt = &r
397		}
398		return y
399	}
400	
401	// canonicalRecord 固定摘要中每个字段的序列化顺序。
402	type canonicalRecord struct {
403		EncounterID ID     `json:"encounter_id"`
404		Category    string `json:"category"`
405		RecordID    ID     `json:"record_id"`
406		VersionID   ID     `json:"version_id"`
407		Version     int    `json:"version"`
408		EffectiveAt string `json:"effective_at"`
409		Content     string `json:"content"`
410	}
411	
412	type canonicalPackage struct {
413		PatientID  ID                `json:"patient_id"`
414		ReceiverID string            `json:"receiver_id"`
415		Records    []canonicalRecord `json:"records"`
416	}
417	
418	// packageDigest 计算包内容的稳定摘要：记录先按标识排序（创建时已排序），
419	// 时间统一为 UTC RFC3339Nano，字段顺序固定，因此与入参顺序无关、可重算核对。
420	func packageDigest(p Package) string {
421		cp := canonicalPackage{
422			PatientID:  p.PatientID,
423			ReceiverID: p.ReceiverID,
424			Records:    make([]canonicalRecord, 0, len(p.Records)),
425		}
426		recs := append([]PackagedRecord(nil), p.Records...)
427		sort.Slice(recs, func(i, j int) bool { return recs[i].RecordID < recs[j].RecordID })
428		for _, r := range recs {
429			cp.Records = append(cp.Records, canonicalRecord{
430				EncounterID: r.EncounterID,
431				Category:    r.Category,
432				RecordID:    r.RecordID,
433				VersionID:   r.VersionID,
434				Version:     r.Version,
435				EffectiveAt: r.EffectiveAt.UTC().Format(time.RFC3339Nano),
436				Content:     r.Content,
437			})
438		}
439		raw, err := json.Marshal(cp)
440		if err != nil {
441			// 参与序列化的都是字符串/整数等基础类型，不应失败。
442			panic(fmt.Errorf("clinical: cannot marshal package digest: %w", err))
443		}
444		sum := sha256.Sum256(raw)
445		return hex.EncodeToString(sum[:])
446	}
447

